template <typename T>
T process(T value) { return value; }

// Explicit specialization for float
template <>
float process(float value) { return value * 10.0f; }

// Template function specialization using a specialized class/type
template <typename T, typename U = int>
T calculate(T a, U b) { return a + b; }

// Template function with a default *value* argument
template <typename T>
T scale(T val, float factor = 1.0f) {
    return val * factor;
}

// Example calls imply behavior:
// int a = scale(5);      // factor = 1.0f
// float f = process(2.0f); // Uses specialization
// int c = calculate(5, 5); // U defaults to int
